package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.util.*;
/** Bounded visible source metadata; never infers hidden columns or script behavior. */
final class SourceDictionary {
 private SourceDictionary() {}
 static String name(Object input){String name=WorkJobs.text(input,80);require(name.matches("[a-z][a-z0-9_]{0,79}"),"Use a valid table name");return name;}
 static Map<String,Object> inspect(String origin,String token,String table){
  var hierarchy=new ArrayList<String>();String filter="name="+table;var seen=new HashSet<String>();
  while(true){var rows=ServiceNowSource.page(origin,token,"sys_db_object",filter,"","sys_id,name,super_class");require(rows.size()==1,"Source table metadata is unavailable or ambiguous");var row=rows.getFirst();String current=name(ServiceNowSource.text(row,"name"));if(hierarchy.isEmpty())require(current.equals(table),"Source returned another table");else require(row.get("sys_id").equals(filter.substring(7)),"Source returned another parent identity");require(seen.add(current),"Source inheritance is cyclic");require(hierarchy.size()<5,"Source inheritance exceeds five levels");hierarchy.add(current);String parent=ServiceNowSource.text(row,"super_class");if(parent.isEmpty())break;require(parent.matches("[0-9a-f]{32}"),"Invalid source parent identity");filter="sys_id="+parent;}
  var all=new ArrayList<Map<String,Object>>();String cursor="";while(true){var rows=ServiceNowSource.page(origin,token,"sys_dictionary","nameIN"+String.join(",",hierarchy),cursor,"sys_id,name,element,internal_type,column_label,mandatory,max_length,reference");all.addAll(rows);require(all.size()<=500,"Visible dictionary exceeds500 rows; use a narrower migration plan");if(rows.size()<ServiceNowSource.PAGE)break;cursor=rows.getLast().get("sys_id").toString();}
  var byTable=new LinkedHashMap<String,Map<String,Object>>();for(String parent:hierarchy)byTable.put(parent,map());for(var row:all){String declared=ServiceNowSource.text(row,"name"),field=ServiceNowSource.text(row,"element");require(byTable.containsKey(declared),"Source returned unrelated dictionary metadata");if(field.isEmpty())continue;require(field.matches("[a-z][a-z0-9_]{0,63}"),"Invalid source field name");require(!byTable.get(declared).containsKey(field),"Duplicate dictionary entry requires manual review");String type=ServiceNowSource.text(row,"internal_type"),label=ServiceNowSource.text(row,"column_label");require(type.length()<=80 && label.length()<=320,"Source field metadata exceeds its limit");boolean eligible=!field.startsWith("sys_") && !field.matches(".*(?:password|token|secret|credential).*") && Set.of("string","integer","decimal","float","boolean","glide_date","glide_date_time").contains(type);byTable.get(declared).put(field,map("name",field,"declared_on",declared,"type",type,"label",label,"eligible",eligible,"reason",eligible?"Review type and choice meanings before importing":"System, credential, reference, journal or unsupported type; map manually outside this guided workflow"));}
  var fields=map();for(String parent:hierarchy)for(var entry:byTable.get(parent).entrySet())fields.putIfAbsent(entry.getKey(),entry.getValue());require(!fields.isEmpty(),"No visible source fields were returned");return map("hierarchy",hierarchy,"fields",fields);
 }
}
